import json
from pathlib import Path

import pandas as pd
import streamlit as st


st.set_page_config(
    page_title="ExamGuard — Event Log",
    page_icon="📋",
    layout="wide",
)


LOG_PATH = Path("logs/events.json")


st.title("Event Log")
st.caption(
    "Complete behavioural event history generated by ExamGuard."
)


def load_events():

    if not LOG_PATH.exists():
        return []

    try:

        return json.loads(
            LOG_PATH.read_text(
                encoding="utf-8"
            )
        )

    except json.JSONDecodeError:

        return []


events = load_events()


if not events:

    st.info("No events have been logged yet.")

else:

    rows = []

    for event in reversed(events):

        rows.append(
            {
                "Timestamp":
                    event.get("timestamp"),

                "Student":
                    event.get("student_id"),

                "Behaviour":
                    event.get("behaviour_type"),

                "Confidence":
                    event.get("confidence"),

                "Explanation":
                    event.get("explanation"),
            }
        )


    df = pd.DataFrame(rows)


    st.metric(
        "Total Events",
        len(df),
    )


    st.dataframe(
        df,
        use_container_width=True,
        height=650,
    )